import {PLAYERS,parseCSV,normalize,googleRows,playerStats,fighterStats,slug} from './stats.js';
import {renderWinSpread} from './win-spread.js';
import {createMatchups} from './matchups.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>v===null||v===undefined?'—':new Intl.NumberFormat('en-US').format(v);
const pct=v=>v===null||v===undefined?'—':`${(v*100).toFixed(1)}%`;
const avg=v=>v===null||v===undefined?'—':v.toFixed(2);
const shortDate=d=>new Date(`${d}T12:00:00`).toLocaleDateString('en-US',{month:'short',day:'numeric'});
const fullDate=d=>new Date(`${d}T12:00:00`).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
const SHEET='https://docs.google.com/spreadsheets/d/1b1v5wXmFNisoaZ05FmRcf0JE_WSBQdaamt9mQmIc8kg/';
const state={all:[],filtered:[],skipped:[],source:'snapshot',updated:null,chart:'wins',page:1,view:'overview',refreshing:false};
const art=name=>`assets/${slug(name)}.png`;
const thumb=name=>`assets/thumbs/${slug(name)}.png`;
const image=(name,cls='fighter-image')=>name?`<img class="${cls}" src="${esc(thumb(name))}" alt="" loading="lazy" data-fallback>`:'<span class="cell-subtle">Not recorded</span>';
const empty=message=>`<div class="empty-state"><strong>No matches here yet.</strong>${message}</div>`;
function wireImages(){ $$('img[data-fallback]').forEach(img=>{img.onerror=()=>{img.onerror=null;img.src='assets/fighter-fallback.svg';};});}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500);}
function sortedPlayers(metric){return [...playerStats(state.filtered)].sort((a,b)=>(b[metric]??-1)-(a[metric]??-1));}
function updateStatus(){const dot=$('#connection-dot');dot.className=`status-dot ${state.source==='live'?'live':'cached'}`;const when=state.updated?new Date(state.updated).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}):null;$('#connection-status').textContent=state.source==='live'?`Live · synced ${when}`:state.source==='cache'?`Cached · ${when||'last successful sync'}`:'Saved snapshot · Nov 12';$('#connection-status').title='Checks the live Smash tab every 60 seconds while this page is visible.';}
function applyFilters(resetPage=true){const preset=$('#date-preset').value;let from='',to='';const latest=state.all.at(-1)?.date;if(preset==='session')from=to=latest||'';else if(preset==='30'&&latest){const d=new Date(`${latest}T12:00:00`);d.setDate(d.getDate()-29);from=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;to=latest;}else if(preset==='custom'){from=$('#date-from').value;to=$('#date-to').value;}state.filtered=state.all.filter(m=>(!from||m.date>=from)&&(!to||m.date<=to));if(resetPage)state.page=1;$('#custom-dates').hidden=preset!=='custom';const f=state.filtered;$('#period-caption').textContent=f.length?`${shortDate(f[0].date)} – ${fullDate(f.at(-1).date)}`:'No matches in this period';if(preset==='30')$('#period-caption').title='30 days ending with the latest recorded match, rather than today.';else $('#period-caption').title='';renderAll();}
function renderAll(){renderSummary();renderPlayers();renderChart();renderDonut();renderWinSpread($('#win-spread'),state.filtered,fighterDetail);renderComfort();$('#recent-table').innerHTML=matchTable([...state.filtered].reverse().slice(0,5));renderFighters();renderMatches();matchups.update(state.filtered);wireImages();}
function renderSummary(){const p=playerStats(state.filtered),win=sortedPlayers('wins')[0],kills=sortedPlayers('kills')[0],rate=sortedPlayers('avg')[0];const n=state.filtered.length;const tied=(metric,val)=>p.filter(x=>x[metric]===val).map(x=>x.name).join(' / ');$('#summary').innerHTML=[['MATCHES PLAYED',num(n),'▦',`${new Set(state.filtered.map(m=>m.date)).size} sessions together`],['MOST WINS',n?num(win.wins):'—','♜',n?`<b>${tied('wins',win.wins)}</b> · ${pct(win.winRate)} win rate`:'No recorded matches'],['MOST KILLS',n?num(kills.kills):'—','⌁',n?`<b>${tied('kills',kills.kills)}</b> · total recorded KOs`:'No recorded matches'],['BEST KILLS / GAME',avg(rate.avg),'↗',rate.avg!==null?`<b>${tied('avg',rate.avg)}</b> · ${num(rate.killGames)} scored games`:'No recorded kills']].map(([label,value,symbol,desc])=>`<div class="stat-card"><div class="stat-label">${label}</div><span class="stat-symbol" aria-hidden="true">${symbol}</span><div class="stat-value">${value}</div><div class="stat-description">${desc}</div></div>`).join('');}
function renderPlayers(){const ranks=sortedPlayers('wins');$('#player-cards').innerHTML=playerStats(state.filtered).map(p=>`<article class="player-card" style="--player:${p.color}"><div class="player-card-top"><span class="avatar">${p.id}</span><div><h3>${p.name}</h3><p>${num(p.wins)} W · ${num(p.winGames-p.wins)} L${state.filtered.length-p.winGames?` · ${state.filtered.length-p.winGames} unknown`:''}</p></div><span class="rank-label">0${ranks.findIndex(x=>x.wins===p.wins)+1}</span></div><div class="player-card-numbers"><div><strong>${pct(p.winRate)}</strong><span>WIN RATE</span></div><div><strong>${num(p.kills)}</strong><span>TOTAL KILLS</span></div><div><strong>${avg(p.avg)}</strong><span>KILLS / GAME</span></div></div><div class="player-win-bar"><div style="width:${(p.winRate||0)*100}%"></div></div><div class="player-main"><span>Most played <b>${esc(p.main?.[0]||'Not recorded')}</b></span><span title="Most kills by this player in a single recorded game">Best game <b>${num(p.best)} KOs</b></span></div></article>`).join('');}
function renderChart(){const sessions=[...new Set(state.filtered.map(m=>m.date))];const totals=[0,0,0];const series=sessions.map(date=>{const games=state.filtered.filter(m=>m.date===date);PLAYERS.forEach((p,i)=>totals[i]+=games.reduce((n,m)=>n+(state.chart==='wins'?(m.winner===p.id?1:0):(m.kills[i]??0)),0));return {date,values:[...totals]};});$('#chart-caption').textContent=`Cumulative ${state.chart==='wins'?'wins':'recorded kills'} by session`;$('#chart-tooltip').hidden=true;if(!series.length){$('#trend-chart').innerHTML=empty('Try a different date range.');return;}const W=680,H=255,L=36,R=24,T=20,B=33,w=W-L-R,h=H-T-B;const maximum=Math.max(1,...totals),step=Math.max(1,Math.ceil(maximum/4/10)*10),maxY=maximum<=8?8:step*4;const x=i=>L+(series.length===1?w/2:i/(series.length-1)*w),y=v=>T+h-v/maxY*h;const grid=Array.from({length:5},(_,i)=>{const val=maxY*i/4;return `<line x1="${L}" y1="${y(val)}" x2="${W-R}" y2="${y(val)}" stroke="#eceee5" stroke-dasharray="3 4"/><text x="${L-10}" y="${y(val)+3}" text-anchor="end" fill="#a0a795" font-size="9">${num(val)}</text>`;}).join('');const indices=[...new Set([0,Math.round((series.length-1)/3),Math.round((series.length-1)*2/3),series.length-1])];const labels=indices.map(i=>`<text x="${x(i)}" y="${H-8}" text-anchor="middle" fill="#a0a795" font-size="9">${shortDate(series[i].date)}</text>`).join('');const lines=PLAYERS.map((p,j)=>`<path d="${series.map((s,i)=>`${i?'L':'M'} ${x(i)} ${y(s.values[j])}`).join(' ')}" fill="none" stroke="${p.color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${x(series.length-1)}" cy="${y(totals[j])}" r="3.5" fill="${p.color}" stroke="white" stroke-width="2"/>`).join('');const targets=series.map((s,i)=>`<rect data-point="${i}" tabindex="0" role="button" aria-label="${fullDate(s.date)}: ${PLAYERS.map((p,j)=>`${p.name} ${s.values[j]}`).join(', ')} ${state.chart}" x="${x(i)-(series.length===1?w/2:w/series.length/2)}" y="${T}" width="${series.length===1?w:w/series.length+2}" height="${h}" fill="transparent"/>`).join('');$('#trend-chart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="group" aria-label="Cumulative ${state.chart} for Gautam, Robert, and Varad">${grid}${labels}${lines}<line id="chart-guide" x1="0" x2="0" y1="${T}" y2="${T+h}" stroke="#c9cebd" stroke-dasharray="3 3" visibility="hidden"/>${targets}</svg>`;$$('[data-point]').forEach(el=>{const show=()=>{const i=Number(el.dataset.point),s=series[i];const tip=$('#chart-tooltip');tip.innerHTML=`<b>${fullDate(s.date)}</b>${PLAYERS.map((p,j)=>`<span><i class="dot" style="background:${p.color}"></i>${p.name}<strong>${num(s.values[j])}</strong></span>`).join('')}`;tip.hidden=false;const panel=$('.chart-panel');tip.style.left=`${Math.min(panel.clientWidth-150,Math.max(20,(x(i)/W)*(panel.clientWidth-35)-70))}px`;const guide=$('#chart-guide');guide.setAttribute('x1',x(i));guide.setAttribute('x2',x(i));guide.setAttribute('visibility','visible');};el.onpointerenter=show;el.onfocus=show;el.onclick=show;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show();}};});$('#trend-chart').onpointerleave=()=>{$('#chart-tooltip').hidden=true;$('#chart-guide')?.setAttribute('visibility','hidden');};}
function renderDonut(){const p=sortedPlayers('wins'),total=p.reduce((n,x)=>n+x.wins,0);let start=0;const gradient=p.map(x=>{const end=start+(total?x.wins/total*100:0);const s=`${x.color} ${start}% ${end}%`;start=end;return s;}).join(',');$('#win-donut').innerHTML=`<div class="donut" style="background:${total?`conic-gradient(${gradient})`:'#eeeee5'}" role="img" aria-label="${p.map(x=>`${x.name} ${pct(x.winRate)}`).join(', ')}"><div class="donut-center"><strong>${num(total)}</strong><span>DECIDED MATCHES</span></div></div>`;$('#win-ranking').innerHTML=p.map(x=>`<div class="rank-row"><i class="dot" style="background:${x.color}"></i><span>${x.name}</span><span class="rank-percent">${pct(x.winRate)}</span><strong>${num(x.wins)}</strong></div>`).join('');$('#decided-note').textContent=`${state.filtered.length-total} games without a winner are excluded from win rates.`;}
function renderComfort(){$('#comfort-picks').innerHTML=PLAYERS.map(p=>{const f=fighterStats(state.filtered,p.id).sort((a,b)=>b.picks-a.picks||a.name.localeCompare(b.name))[0];if(!f)return `<div class="comfort-card" style="--player:${p.color}"><span class="comfort-player">${p.name}'s most played</span><h3>No picks recorded</h3></div>`;return `<button class="comfort-card" style="--player:${p.color}" data-fighter="${esc(f.name)}" aria-label="Explore ${esc(f.name)} statistics"><div class="comfort-text"><span class="comfort-player">${p.name}'s most played</span><h3>${esc(f.name)}</h3><div class="pick-count">${num(f.picks)} picks · ${pct(f.pickRate)} pick share</div><div class="mini-stats"><div><strong>${pct(f.winRate)}</strong><span>WIN RATE</span></div><div><strong>${avg(f.avg)}</strong><span>KILLS / GAME</span></div></div></div><img src="${['Ike','Captain Falcon','Zelda'].includes(f.name)?art(f.name):thumb(f.name)}" alt="" loading="lazy" data-fallback></button>`;}).join('');bindFighterLinks();}
function renderFighters(){const player=$('#fighter-player').value,min=Number($('#fighter-min').value),search=$('#fighter-search').value.toLowerCase(),sort=$('#fighter-sort').value;const all=fighterStats(state.filtered,player),list=all.filter(f=>f.picks>=min&&f.name.toLowerCase().includes(search)).sort((a,b)=>(b[sort]??-1)-(a[sort]??-1)||b.picks-a.picks||a.name.localeCompare(b.name));const recorded=all.reduce((n,f)=>n+f.picks,0),possible=state.filtered.length*(player==='all'?3:1);$('#fighter-context').textContent=`${list.length} fighters · ${num(recorded)} recorded picks of ${num(possible)} possible${player==='all'?' · each player selection counts as one pick':''}`;$('#fighter-table').innerHTML=!list.length?empty('Try another player, a lower minimum, or a different date range.'):`<table><thead><tr><th>FIGHTER</th><th>PICKS / SHARE</th><th>WINS</th><th>WIN %</th><th>TOTAL KILLS</th><th>KILLS / GAME</th></tr></thead><tbody>${list.map((f,i)=>`<tr><td><button class="fighter-link" data-fighter="${esc(f.name)}"><span class="row-rank">${String(i+1).padStart(2,'0')}</span>${image(f.name)}<span><strong>${esc(f.name)}</strong>${f.picks<10?'<small class="sample-note"> Small sample</small>':''}</span></button></td><td>${num(f.picks)} <span class="cell-subtle">/ ${pct(f.pickRate)}</span></td><td>${num(f.wins)}</td><td>${pct(f.winRate)}<div class="rate-bar"><span style="width:${(f.winRate||0)*100}%"></span></div></td><td>${f.killGames?num(f.kills):'—'}</td><td>${avg(f.avg)} <span class="cell-subtle">(${num(f.killGames)})</span></td></tr>`).join('')}</tbody></table>`;bindFighterLinks();wireImages();}
function bindFighterLinks(){$$('[data-fighter]').forEach(btn=>btn.onclick=()=>fighterDetail(btn.dataset.fighter));}
function fighterDetail(name){const rows=PLAYERS.map(p=>({...p,stats:fighterStats(state.filtered,p.id).find(f=>f.name===name)}));$('#dialog-content').innerHTML=`<div class="dialog-head"><img src="${esc(thumb(name))}" alt="" data-fallback><div><div class="eyebrow">FIGHTER BREAKDOWN</div><h2>${esc(name)}</h2><p>${esc($('#period-caption').textContent)} · recorded picks only</p></div></div><div class="table-scroll"><table class="dialog-table"><thead><tr><th>PLAYER</th><th>PICKS</th><th>WINS</th><th>WIN %</th><th>KILLS</th><th>KILLS / GAME</th></tr></thead><tbody>${rows.map(p=>{const f=p.stats;return `<tr><td><i class="dot" style="background:${p.color};margin-right:7px"></i>${p.name}</td><td>${f?num(f.picks):'0'}</td><td>${f?num(f.wins):'0'}</td><td>${pct(f?.winRate)}</td><td>${f?.killGames?num(f.kills):'—'}</td><td>${avg(f?.avg)}</td></tr>`;}).join('')}</tbody></table></div><p class="dialog-note">Win % = wins ÷ character picks in decided matches. Kills / game = recorded kills ÷ picks with a kill score. A dash means there is no recorded sample. Choosing the same fighter on two players counts as two picks.</p>`;wireImages();$('#detail-dialog').showModal();}
function filteredHistory(){const query=$('#match-search').value.toLowerCase().trim(),winner=$('#match-winner').value;return [...state.filtered].reverse().filter(m=>(winner==='all'||(winner==='unknown'?!m.winner:m.winner===winner))&&(!query||[String(m.row),m.date,fullDate(m.date),...m.characters,PLAYERS.find(p=>p.id===m.winner)?.name||'unknown'].some(v=>v.toLowerCase().includes(query))));}
function matchTable(matches) {
  if (!matches.length) return empty('Try different filters or a different date range.');
  return `<table><thead><tr><th>MATCH</th><th>WINNER</th><th>GAUTAM</th><th>ROBERT</th><th>VARAD</th></tr></thead><tbody>${matches.map(m => {
    const p = PLAYERS.find(p => p.id === m.winner);
    return `<tr><td class="match-date">${shortDate(m.date)}<small>Sheet row ${m.row}</small></td>
      <td>${p ? `<span class="winner-pill" style="--player:${p.color}"><i class="dot"></i>${p.name}</span>` : '<span class="cell-subtle">Not recorded</span>'}</td>
      ${m.characters.map((character, index) => {
        const kills = m.kills[index];
        const killLabel = kills === null ? 'Kills not recorded' : `${num(kills)} ${kills === 1 ? 'kill' : 'kills'}`;
        return `<td><span class="match-fighter">${character ? image(character) : ''}<span class="match-fighter-label"><span${character ? '' : ' class="cell-subtle"'}>${character ? esc(character) : 'Not recorded'}</span><small class="match-fighter-kills">${killLabel}</small></span></span></td>`;
      }).join('')}</tr>`;
  }).join('')}</tbody></table>`;
}
function renderMatches(){const matches=filteredHistory(),pages=Math.max(1,Math.ceil(matches.length/20));state.page=Math.min(state.page,pages);$('#match-count').textContent=`${num(matches.length)} matches · newest first · original Google Sheet row numbers`;$('#matches-table').innerHTML=matchTable(matches.slice((state.page-1)*20,state.page*20));$('#page-info').textContent=`Page ${state.page} of ${pages}`;$('#prev-page').disabled=state.page===1;$('#next-page').disabled=state.page===pages;wireImages();}
function exportCSV(){const rows=[['Date','Winner','G kills','R kills','V kills','G character','R character','V character','Sheet row'],...filteredHistory().map(m=>[m.date,m.winner||'',...m.kills.map(k=>k??''),...m.characters,m.row])];const csv=rows.map(row=>row.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.href=url;a.download='smash-club-matches.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Exported ${rows.length-1} matches.`);}
function showView(){const view=location.hash.slice(1);state.view=['overview','fighters','matchups','matches'].includes(view)?view:'overview';const text={overview:['Overview','The bigger picture','Every win, every KO, every “one more game.”'],fighters:['Fighter lab','Find your winning formula','Your picks, your patterns, and the fighters that deliver.'],matchups:['Matchups','Same lineup. New story','Compare the exact same player and fighter assignments, game after game.'],matches:['Match history','Every game has a story','The complete match log, straight from your Google Sheet.']}[state.view];$$('.view').forEach(v=>v.hidden=v.id!==`${state.view}-view`);$$('.nav-link').forEach(a=>{a.classList.toggle('active',a.dataset.view===state.view);if(a.dataset.view===state.view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#breadcrumb-current').textContent=text[0];$('#page-title').innerHTML=`${text[1]}<span>.</span>`;$('#page-subtitle').textContent=text[2];}
function methodology(){const all=state.all,unknown=all.filter(m=>!m.winner).length,missing=all.reduce((n,m)=>n+m.characters.filter(c=>!c).length,0),killMissing=all.reduce((n,m)=>n+m.kills.filter(k=>k===null).length,0);$('#dialog-content').innerHTML=`<div class="methodology"><div class="eyebrow">THE RECEIPTS BEHIND THE RECEIPTS</div><h2>Live data. Clear definitions.</h2><p>Source: the <a href="${SHEET}edit?gid=588458277#gid=588458277" target="_blank" rel="noreferrer">Smash tab in your Google Sheet</a>. Only columns A–H are read. The dashboard reloads it on opening, every 60 seconds while visible, and when you press refresh. Google may briefly cache its response.</p><h3>Your structure already works</h3><p>A: date, B: winner (G / R / V), C–E: kills for Gautam, Robert, Varad, F–H: their characters. Blank dates inherit the closest date above. Dates without a year inherit the last explicit year (2026 for the original log). Keep these eight columns in order and the tab named Smash.</p><h3>What gets cleaned on every load</h3><p>Winner initials are case-insensitive. Character names are trimmed and matched without case. DK → Donkey Kong; Pokémon / Pokemon Trainer are merged; Mr. Game and Watch → Mr. Game & Watch; Rosalina → Rosalina & Luma; Lemmy → Bowser Jr. Blank kills stay missing; zero is a valid kill score. Rows with no winner and no kill scores are excluded.</p><h3>What the numbers mean</h3><p><b>Most kills:</b> sum of recorded kill scores. <b>Best kills / game:</b> total kills divided by games with a kill score, calculated separately per player. <b>Win rate:</b> wins divided by matches with a known winner. <b>Character win rate:</b> wins with that fighter divided by their picks in decided games. <b>Pick share:</b> that fighter’s picks divided by all recorded picks for the selected player(s). A mirror match counts each selection separately.</p><h3>Win concentration & breadth</h3><p>The win-spread chart ranks each player’s fighters separately by wins and plots their cumulative share of wins with a recorded fighter. Top-three share is the fraction of these wins from up to three leading fighters. Effective fighters = 1 ÷ Σ(character win share²); a higher number means a broader spread, equivalent to that many fighters winning equally often. Missing winning characters are excluded and their counts are shown. This describes win distribution, which also reflects pick frequency; it does not establish equal skill across fighters. The expandable table shows character win rates alongside win shares.</p><h3>Exact matchups</h3><p>The Matchups tab groups games by the ordered fighter picks for Gautam, Robert, and Varad. Assignments are fixed: swapping fighters between players creates a separate group. Games missing any fighter are excluded. Lineups can be filtered by each player’s fighter, minimum games, and multiple sessions. A session is a calendar date. The report shows wins, win rates, kills per scored game, cumulative wins, a session breakdown, and the exact games included. All figures follow the global match period and update with the live sheet.</p><h3>Data coverage right now</h3><p>${num(all.length)} matches · ${num(unknown)} unknown winners · ${num(killMissing)} missing player kill scores · ${num(missing)} missing character picks. ${state.skipped.length} incomplete rows excluded${state.skipped.length?` (sheet rows ${state.skipped.join(', ')})`:''}. These coverage counts describe the full loaded sheet, before filters.</p><h3>Connection & artwork</h3><p>If Google cannot be reached, this browser uses its last successful copy, or the bundled Nov 12, 2026 snapshot on a first visit. The status always identifies live, cached, or saved data. The sheet must remain readable through its shared link. No Google credentials are stored in this app.</p><p>Character artwork comes from the <a href="https://www.smashbros.com/en_US/fighter/index.html" target="_blank" rel="noreferrer">official Super Smash Bros. Ultimate fighter roster</a>. Character and game rights belong to Nintendo and their respective owners. This is an unofficial personal stats dashboard.</p></div>`;$('#detail-dialog').showModal();}
function loadLive(){return new Promise((resolve,reject)=>{const callback=`smashSheet_${Date.now()}`,script=document.createElement('script');let timeout;const cleanup=()=>{clearTimeout(timeout);script.remove();delete window[callback];};window[callback]=payload=>{cleanup();if(payload.status==='error'||!payload.table?.rows){reject(new Error('Sheet returned no table'));return;}resolve(normalize(googleRows(payload)));};script.onerror=()=>{cleanup();reject(new Error('Could not reach Google Sheets'));};timeout=setTimeout(()=>{cleanup();reject(new Error('Google Sheets request timed out'));},18000);const params=new URLSearchParams({sheet:'Smash',range:'A:H',headers:'1',tqx:`out:json;responseHandler:${callback}`,_:String(Date.now())});script.src=`${SHEET}gviz/tq?${params}`;document.head.appendChild(script);});}
async function refresh(manual=false){if(state.refreshing)return;state.refreshing=true;$('#refresh').classList.add('loading');$('#refresh').disabled=true;try{const data=await loadLive();if(!data.matches.length)throw new Error('Sheet contained no usable matches');state.all=data.matches.sort((a,b)=>a.date.localeCompare(b.date)||a.row-b.row);state.skipped=data.skipped;state.source='live';state.updated=new Date().toISOString();try{localStorage.setItem('smash-club-data-v1',JSON.stringify({matches:state.all,skipped:state.skipped,updated:state.updated}));}catch{}$('#data-notice').hidden=true;applyFilters(false);if(manual)toast('Up to date. Fresh data, straight from the Smash tab.');}catch(error){state.source=state.updated?'cache':'snapshot';$('#data-notice').hidden=false;$('#data-notice').textContent='Live refresh unavailable. Showing '+(state.updated?'the last successful sync':'the saved Nov 12 snapshot')+'. We’ll retry automatically. Check that the sheet is still accessible through its shared link.';if(manual)toast('Google Sheets is unavailable. Your saved data is still here.');}finally{state.refreshing=false;$('#refresh').classList.remove('loading');$('#refresh').disabled=false;updateStatus();}}
const matchups = createMatchups($('#matchups-view'), {renderMatchTable:matchTable, onImages:wireImages});
$('#date-preset').onchange=applyFilters;$('#date-from').onchange=applyFilters;$('#date-to').onchange=applyFilters;$('#reset-dates').onclick=()=>{$('#date-from').value='';$('#date-to').value='';applyFilters();};$$('[data-chart]').forEach(button=>button.onclick=()=>{state.chart=button.dataset.chart;$$('[data-chart]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button?'true':'false');});renderChart();});['#fighter-player','#fighter-min','#fighter-sort'].forEach(id=>$(id).onchange=renderFighters);$('#fighter-search').oninput=renderFighters;$('#match-search').oninput=()=>{state.page=1;renderMatches();};$('#match-winner').onchange=()=>{state.page=1;renderMatches();};$('#prev-page').onclick=()=>{state.page--;renderMatches();};$('#next-page').onclick=()=>{state.page++;renderMatches();};$('#export').onclick=exportCSV;$('#refresh').onclick=()=>refresh(true);$('#about-button').onclick=methodology;$('#methodology').onclick=methodology;$('#close-dialog').onclick=()=>$('#detail-dialog').close();$('#detail-dialog').onclick=e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};window.addEventListener('hashchange',showView);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});showView();
async function init(){let cached;try{cached=JSON.parse(localStorage.getItem('smash-club-data-v1'));}catch{}if(cached?.matches?.length){state.all=cached.matches;state.skipped=cached.skipped||[];state.updated=cached.updated;state.source='cache';}else{try{const response=await fetch('smash.csv');if(!response.ok)throw new Error('Snapshot not found');const data=normalize(parseCSV(await response.text()));state.all=data.matches;state.skipped=data.skipped;}catch{$('#data-notice').hidden=false;$('#data-notice').textContent='Loading saved data failed. Trying the live Google Sheet…';}}applyFilters();updateStatus();refresh();setInterval(()=>{if(!document.hidden)refresh();},60000);}init();
